mapper.insert:
INSERT INTO oa_iam.risk_finding (
    tenant_id, rule_code, severity, identity_id, identity_type,
    display_name, external_key, summary, status, detected_at, updated_at
)
SELECT #{tenantId}, #{ruleCode}, #{severity}, CAST(#{identityId} AS uuid), #{identityType},
       #{displayName}, #{externalKey}, #{summary}, 'OPEN', #{detectedAt}, #{updatedAt}
 WHERE NOT EXISTS (
    SELECT 1 FROM oa_iam.risk_finding f
     WHERE f.tenant_id = #{tenantId}
       AND f.rule_code = #{ruleCode}
       AND f.identity_id = CAST(#{identityId} AS uuid)
       AND f.status IN ('OPEN', 'ACKNOWLEDGED', 'IGNORED')
 )

