UPDATE oa_iam.risk_finding
   SET status = #{toStatus},
       note = #{note},
       updated_by = #{updatedBy},
       updated_at = #{updatedAt}
 WHERE tenant_id = #{tenantId}
   AND id = #{id}
   AND status = #{fromStatus}
